def check(inp, actual, expected):
    if not expected:
        return actual == []
    n = inp["numCourses"]
    if sorted(actual) != list(range(n)):
        return False
    pos = {c: i for i, c in enumerate(actual)}
    return all(pos[b] < pos[a] for a, b in inp["prerequisites"])
